14	
15	    private OwnerIdentity() {
16	    }
17	
18	    /**
19	     * Returns the full lower-case (64-character) SHA-256 hex digest of {@code value}'s UTF-8 bytes.
20	     * Deterministic, so the same input always yields the same digest.
21	     */
22	    public static String sha256Hex(String value) {
23	        try {
24	            byte[] digest = MessageDigest.getInstance("SHA-256")
25	                .digest(value.getBytes(StandardCharsets.UTF_8));
26	            StringBuilder sb = new StringBuilder(digest.length * 2);
27	            for (byte b : digest) {
28	                sb.append(String.format("%02x", b));
29	            }
30	            return sb.toString();
31	        }
32	        catch (NoSuchAlgorithmException e) {
33	            throw new IllegalStateException("SHA-256 not available", e);
34	        }
35	    }
36	
37	    /**
38	     * Computes the American Soundex code of {@code name}: the retained first letter followed by three
39	     * digits encoding the remaining consonants ({@code b,f,p,v->1}; {@code c,g,j,k,q,s,x,z->2};
40	     * {@code d,t->3}; {@code l->4}; {@code m,n->5}; {@code r->6}). Adjacent letters sharing a code
41	     * collapse to one digit (letters separated by {@code h} or {@code w} are treated as adjacent,
42	     * while vowels — {@code a,e,i,o,u,y} — break the run), and the result is right-padded with zeros
43	     * and truncated to four characters (e.g. {@code "Robert" -> "R163"}). Returns the empty string
44	     * when the name is {@code null} or contains no letters.
45	     */
46	    public static String soundex(String name) {
47	        if (name == null) {
48	            return "";
49	        }
50	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
51	        if (letters.isEmpty()) {
52	            return "";
53	        }
54	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
55	        char previous = soundexCode(letters.charAt(0));
56	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
57	            char c = letters.charAt(i);
58	            if (c == 'H' || c == 'W') {
59	                continue;
60	            }
61	            char digit = soundexCode(c);
62	            if (digit != '0' && digit != previous) {
63	                code.append(digit);
64	            }
65	            previous = digit;
66	        }
67	        while (code.length() < 4) {
68	            code.append('0');
69	        }
70	        return code.toString();
71	    }
72	
73	    /**
74	     * Maps a single upper-case letter to its Soundex digit, returning {@code '0'} for the vowels
75	     * {@code A,E,I,O,U,Y} and for {@code H,W} (which the caller handles specially).
76	     */
77	    private static char soundexCode(char c) {
78	        return switch (c) {
79	            case 'B', 'F', 'P', 'V' -> '1';
80	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
81	            case 'D', 'T' -> '3';
82	            case 'L' -> '4';
83	            case 'M', 'N' -> '5';
84	            case 'R' -> '6';
85	            default -> '0';
86	        };
87	    }
88	}
