1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.time.LocalDate;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
24	    @Mapping(target = "salutation", source = "owner", qualifiedByName = "toSalutation")
25	    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "toTelephoneDisplay")
26	    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
27	    @Mapping(target = "fiscalYear", source = "owner", qualifiedByName = "toFiscalYear")
28	    @Mapping(target = "membershipPoints", source = "owner", qualifiedByName = "toMembershipPoints")
29	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "toMembershipLevel")
30	    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
31	    @Mapping(target = "timezone", source = "owner", qualifiedByName = "toTimezone")
32	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "toContactPreference")
33	    @Mapping(target = "identityKey", source = "owner", qualifiedByName = "toIdentityKey")
34	    @Mapping(target = "ageBand", source = "owner", qualifiedByName = "toAgeBand")
35	    @Mapping(target = "ownerSegment", source = "owner", qualifiedByName = "toOwnerSegment")
36	    @Mapping(target = "selfLink", source = "owner", qualifiedByName = "toSelfLink")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Derives the owner's {@code selfLink}: its canonical relative URL, {@code '/api/owners/'}
41	     * followed by the owner's id. Returns {@code null} when the owner has no id yet.
42	     */
43	    @Named("toSelfLink")
44	    default String toSelfLink(Owner owner) {
45	        if (owner == null || owner.getId() == null) {
46	            return null;
47	        }
48	        return "/api/owners/" + owner.getId();
49	    }
50	
51	    /**
52	     * Derives the owner's {@code ageBand} from its {@code birthDate}, computed against the
53	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18 on the registration date,
54	     * {@code 'ADULT'} from 18 up to and including 64, and {@code 'SENIOR'} at 65 or over. Returns
55	     * {@code null} when either the birth date or the registration date is absent.
56	     */
57	    @Named("toAgeBand")
58	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
59	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
60	            return null;
61	        }
62	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
63	        if (age < 18) {
64	            return OwnerDto.AgeBandEnum.MINOR;
65	        }
66	        if (age < 65) {
67	            return OwnerDto.AgeBandEnum.ADULT;
68	        }
69	        return OwnerDto.AgeBandEnum.SENIOR;
70	    }
71	
72	    /**
73	     * Derives the owner's duplicate-detection {@code identityKey}: the single key that consolidates
74	     * the former separate telephone, email and household checks. It is the lower-case, 64-character
75	     * SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)},
76	     * where {@code lowerEmail} is the email trimmed and lower-cased (or the empty string when absent)
77	     * and {@code soundex(lastName)} is the American Soundex code of the owner's last name. Because the
78	     * telephone is part of the key, two owners with the same last name (same soundex) and postcode but
79	     * different telephones have different identity keys; only an exact full-key match is a duplicate.
80	     */
81	    @Named("toIdentityKey")
82	    default String toIdentityKey(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
87	        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
88	        String soundex = OwnerIdentity.soundex(owner.getLastName());
89	        return OwnerIdentity.sha256Hex(telephone + "|" + email + "|" + soundex);
90	    }
91	
92	    /**
93	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}: one of
94	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
95	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's {@code membershipLevel}
96	     * is {@code 3} or more, otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's
97	     * locality is a known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise
98	     * {@code 'REGIONAL'}.
99	     */
100	    @Named("toOwnerSegment")
101	    default OwnerDto.OwnerSegmentEnum toOwnerSegment(Owner owner) {
102	        if (owner == null) {
103	            return null;
104	        }
105	        Integer membershipLevel = toMembershipLevel(owner);
106	        boolean premium = membershipLevel != null && membershipLevel >= 3;
107	        boolean metro = REGION_TIMEZONE.containsKey(toLocality(owner));
108	        if (premium) {
109	            return metro ? OwnerDto.OwnerSegmentEnum.PREMIUM_METRO : OwnerDto.OwnerSegmentEnum.PREMIUM_REGIONAL;
110	        }
111	        return metro ? OwnerDto.OwnerSegmentEnum.STANDARD_METRO : OwnerDto.OwnerSegmentEnum.STANDARD_REGIONAL;
112	    }
113	
114	    /**
115	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
116	     * email, otherwise {@code 'PHONE'}.
117	     */
118	    @Named("toContactPreference")
119	    default String toContactPreference(Owner owner) {
120	        if (owner == null) {
121	            return null;
122	        }
123	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
124	        return hasEmail ? "EMAIL" : "PHONE";
125	    }
126	
127	    /**
128	     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
129	     */
130	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
131	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
132	
133	    /**
134	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name
135	     * ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}).
136	     */
137	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
138	        "NSW", "Australia/Sydney",
139	        "VIC", "Australia/Melbourne",
140	        "QLD", "Australia/Brisbane");
141	
142	    /**
143	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
144	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
145	     * owner's locality from its postcode in preference to its city.
146	     */
147	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
148	        "NSW", new int[] {2000, 2099},
149	        "VIC", new int[] {3000, 3099},
150	        "QLD", new int[] {4000, 4099});
151	
152	    /**
153	     * Derives the owner's canonical region, the {@code REGION} component of its {@code memberId}.
154	     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
155	     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
156	     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
157	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
158	     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
159	     * the same region for known cities but disambiguates cities that share a name.
160	     */
161	    default String toRegion(Owner owner) {
162	        if (owner == null) {
163	            return null;
164	        }
165	        String regionByPostcode = regionForPostcode(owner.getPostcode());
166	        if (regionByPostcode != null) {
167	            return regionByPostcode;
168	        }
169	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
170	    }
171	
172	    /**
173	     * Derives the owner's locality as the {@code REGION} component of its {@code memberId} (the prefix
174	     * before the fixed {@code <FY><HASH8><CHK>} tail). The locality therefore shares the member id's
175	     * identity rather than being computed independently. When the member id is absent the region is
176	     * derived directly from the owner's postcode and city via {@link #toRegion(Owner)}.
177	     */
178	    @Named("toLocality")
179	    default String toLocality(Owner owner) {
180	        if (owner == null) {
181	            return null;
182	        }
183	        String region = regionFromMemberId(owner.getMemberId());
184	        if (region != null) {
185	            return region;
186	        }
187	        return toRegion(owner);
188	    }
189	
190	    /** The fixed-width tail of a memberId's {@code <REGION><FY><HASH8><CHK>} core: FY (2) + HASH8 (8) + CHK (1). */
191	    int MEMBER_ID_TAIL_LENGTH = 11;
192	
193	    /**
194	     * Returns the {@code <REGION><FY><HASH8><CHK>} core of a {@code memberId}, stripping any
195	     * collision-dedup suffix ({@code '-<n>'}). Returns {@code null} when {@code memberId} is
196	     * {@code null}.
197	     */
198	    private static String memberIdCore(String memberId) {
199	        if (memberId == null) {
200	            return null;
201	        }
202	        int dash = memberId.indexOf('-');
203	        return dash >= 0 ? memberId.substring(0, dash) : memberId;
204	    }
205	
206	    /**
207	     * Extracts the {@code REGION} component (the prefix before the fixed {@code <FY><HASH8><CHK>}
208	     * tail) from a {@code memberId}, or {@code null} when the id is absent or too short to carry one.
209	     */
210	    private static String regionFromMemberId(String memberId) {
211	        String core = memberIdCore(memberId);
212	        if (core == null || core.length() <= MEMBER_ID_TAIL_LENGTH) {
213	            return null;
214	        }
215	        return core.substring(0, core.length() - MEMBER_ID_TAIL_LENGTH);
216	    }
217	
218	    /**
219	     * Extracts the 2-digit {@code FY} component of a {@code memberId} (the two characters immediately
220	     * following its {@code REGION} prefix), or {@code null} when the id is absent or too short.
221	     */
222	    private static String fiscalYearFromMemberId(String memberId) {
223	        String core = memberIdCore(memberId);
224	        if (core == null || core.length() <= MEMBER_ID_TAIL_LENGTH) {
225	            return null;
226	        }
227	        int fyStart = core.length() - MEMBER_ID_TAIL_LENGTH;
228	        return core.substring(fyStart, fyStart + 2);
229	    }
230	
231	    /**
232	     * Derives the owner's {@code timezone} as the IANA timezone name mapped from its locality/region
233	     * via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
234	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Returns {@code null} when the
235	     * owner's region is not one of the tabled regions.
236	     */
237	    @Named("toTimezone")
238	    default String toTimezone(Owner owner) {
239	        if (owner == null) {
240	            return null;
241	        }
242	        return REGION_TIMEZONE.get(toLocality(owner));
243	    }
244	
245	    /**
246	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
247	     * {@code null} when the postcode is absent, malformed, or in no known range.
248	     */
249	    private static String regionForPostcode(String postcode) {
250	        if (postcode == null || !postcode.matches("\\d{4}")) {
251	            return null;
252	        }
253	        int value = Integer.parseInt(postcode);
254	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
255	            int[] range = entry.getValue();
256	            if (value >= range[0] && value <= range[1]) {
257	                return entry.getKey();
258	            }
259	        }
260	        return null;
261	    }
262	
263	    /**
264	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
265	     */
266	    @Named("toDisplayName")
267	    default String toDisplayName(Owner owner) {
268	        if (owner == null) {
269	            return null;
270	        }
271	        return owner.getLastName() + ", " + owner.getFirstName();
272	    }
273	
274	    /**
275	     * Composes the owner's {@code salutation}: the owner's {@code title} and {@code lastName} joined
276	     * by a single space when a title is present, or just the {@code lastName} when no title is
277	     * supplied (absent or blank).
278	     */
279	    @Named("toSalutation")
280	    default String toSalutation(Owner owner) {
281	        if (owner == null) {
282	            return null;
283	        }
284	        String title = owner.getTitle();
285	        if (title == null || title.isBlank()) {
286	            return owner.getLastName();
287	        }
288	        return title + " " + owner.getLastName();
289	    }
290	
291	    /**
292	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
293	     * the national digits grouped in threes, e.g. {@code "+61412345678"} becomes
294	     * {@code "+61 412 345 678"}. The country code is a single {@code '1'} for NANP ({@code +1}) numbers
295	     * and two digits otherwise (covering the {@code +61} numbers the app stores). Returns the value
296	     * unchanged when it is absent or not a well-formed E.164 number, leaving raw {@code telephone}
297	     * untouched.
298	     */
299	    @Named("toTelephoneDisplay")
300	    default String toTelephoneDisplay(Owner owner) {
301	        if (owner == null) {
302	            return null;
303	        }
304	        String telephone = owner.getTelephone();
305	        if (telephone == null || !telephone.matches("\\+[0-9]{8,15}")) {
306	            return telephone;
307	        }
308	        String digits = telephone.substring(1);
309	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
310	        String countryCode = digits.substring(0, countryCodeLength);
311	        String national = digits.substring(countryCodeLength);
312	        StringBuilder sb = new StringBuilder("+").append(countryCode);
313	        for (int i = 0; i < national.length(); i++) {
314	            if (i % 3 == 0) {
315	                sb.append(' ');
316	            }
317	            sb.append(national.charAt(i));
318	        }
319	        return sb.toString();
320	    }
321	
322	    /**
323	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
324	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
325	     */
326	    @Named("toInitials")
327	    default String toInitials(Owner owner) {
328	        if (owner == null) {
329	            return null;
330	        }
331	        return initial(owner.getFirstName()) + initial(owner.getLastName());
332	    }
333	
334	    /**
335	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'} where {@code YY} is the
336	     * 2-digit fiscal-year segment carried inside the owner's {@code memberId} (e.g. {@code 'FY26'}).
337	     * The fiscal year starts on 1 July and is identified by the calendar year in which it ends; that
338	     * value was stamped into the member id from the business-day-adjusted registration date at
339	     * creation. Returns {@code null} when the member id is absent.
340	     */
341	    @Named("toFiscalYear")
342	    default String toFiscalYear(Owner owner) {
343	        if (owner == null) {
344	            return null;
345	        }
346	        String fy = fiscalYearFromMemberId(owner.getMemberId());
347	        return fy == null ? null : "FY" + fy;
348	    }
349	
350	    /**
351	     * Returns the fiscal year of the given date as the calendar year in which the fiscal year ends.
352	     * The fiscal year starts on 1 July, so a date in July or later belongs to the fiscal year ending
353	     * in the next calendar year ({@code year + 1}); an earlier date belongs to the fiscal year ending
354	     * in its own calendar year.
355	     *
356	     * @param date the date whose fiscal year is computed, never {@code null}
357	     * @return the calendar year in which the date's fiscal year ends
358	     */
359	    static int fiscalYear(LocalDate date) {
360	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
361	    }
362	
363	    /**
364	     * Returns the owner's membership points, assigned on creation: starts at {@code 0}, plus {@code 2}
365	     * when a non-blank email is present, plus {@code 1} when the owner has no namesakes
366	     * ({@code namesakeCount} is 0), plus {@code 2} for a household of {@code 3} or more members, plus
367	     * {@code 3} for a tenure of one or more elapsed fiscal years since the {@code registrationDate}.
368	     * This qualified mapping cannot observe the owner's household size (which requires counting other
369	     * owners), so it computes the points as if the owner were the only member of its household; the
370	     * controller recomputes the points with the real household size via
371	     * {@link #membershipPointsFor(Owner, int)} before returning the owner.
372	     */
373	    @Named("toMembershipPoints")
374	    default Integer toMembershipPoints(Owner owner) {
375	        if (owner == null) {
376	            return null;
377	        }
378	        return membershipPointsFor(owner, 1);
379	    }
380	
381	    /**
382	     * Returns the owner's numeric membership level, derived from its membership points: level
383	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
384	     * {@code 4} for {@code 6} or more. As with {@link #toMembershipPoints(Owner)}, the household size
385	     * is not observable here and is treated as a single member.
386	     */
387	    @Named("toMembershipLevel")
388	    default Integer toMembershipLevel(Owner owner) {
389	        if (owner == null) {
390	            return null;
391	        }
392	        return membershipLevelFor(membershipPointsFor(owner, 1));
393	    }
394	
395	    /**
396	     * Computes an owner's membership points from the given household size: starts at {@code 0}, plus
397	     * {@code 2} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
398	     * ({@code namesakeCount} is 0), plus {@code 2} when {@code householdSize} is {@code 3} or more,
399	     * plus {@code 3} for a tenure of one or more elapsed fiscal years (each starting 1 July) between
400	     * the {@code registrationDate} and today.
401	     *
402	     * @param owner the owner whose points are computed, never {@code null}
403	     * @param householdSize the number of owners sharing the owner's household
404	     * @return the owner's membership points
405	     */
406	    static int membershipPointsFor(Owner owner, int householdSize) {
407	        int points = 0;
408	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
409	        if (hasEmail) {
410	            points += 2;
411	        }
412	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
413	        if (noNamesakes) {
414	            points += 1;
415	        }
416	        if (householdSize >= 3) {
417	            points += 2;
418	        }
419	        boolean tenured = owner.getRegistrationDate() != null
420	            && fiscalYear(LocalDate.now()) - fiscalYear(owner.getRegistrationDate()) >= 1;
421	        if (tenured) {
422	            points += 3;
423	        }
424	        return points;
425	    }
426	
427	    /**
428	     * Maps membership points to the numeric membership level: level {@code 1} for {@code 0-1} points,
429	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
430	     *
431	     * @param points the owner's membership points
432	     * @return the corresponding membership level (1-4)
433	     */
434	    static int membershipLevelFor(int points) {
435	        if (points <= 1) {
436	            return 1;
437	        }
438	        if (points <= 3) {
439	            return 2;
440	        }
441	        if (points <= 5) {
442	            return 3;
443	        }
444	        return 4;
445	    }
446	
447	    private static String initial(String name) {
448	        if (name == null || name.isEmpty()) {
449	            return "";
450	        }
451	        return Character.toUpperCase(name.charAt(0)) + ".";
452	    }
453	
454	    Owner toOwner(OwnerDto ownerDto);
455	
456	    @Mapping(target = "id", ignore = true)
457	    @Mapping(target = "pets", ignore = true)
458	    Owner toOwner(OwnerFieldsDto ownerDto);
459	
460	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
461	
462	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
463	
