595	    /**
596	     * Caps the owner's {@code membershipLevel} so it cannot exceed one above the current maximum
597	     * membership level among the other members of its household (existing owners carrying the same
598	     * {@code householdId}, excluding the owner itself and any soft-deleted owner). When the household
599	     * has no other member — including when the owner has no {@code householdId} — no cap applies and
600	     * {@code level} is returned unchanged. Each household member's level is its own base level (points
601	     * mapped to a level for its real household size), so the cap does not depend on other capped
602	     * values.
603	     *
604	     * @param owner the owner whose membership level is being computed
605	     * @param level the owner's uncapped membership level derived from its membership points
606	     * @return the membership level capped at {@code maxHouseholdMemberLevel + 1}, or {@code level}
607	     *         when the owner has no other household member
608	     */
609	    private int capMembershipLevel(Owner owner, int level) {
610	        String householdId = owner.getHouseholdId();
611	        if (householdId == null) {
612	            return level;
613	        }
614	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
615	            .filter(existing -> !isDeleted(existing))
616	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
617	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
618	            .map(this::membershipLevelForOwner)
619	            .max(Integer::compareTo)
620	            .orElse(null);
621	        if (maxMemberLevel == null) {
622	            return level;
623	        }
624	        return Math.min(level, maxMemberLevel + 1);
625	    }
