627	    /**
628	     * Computes an existing household member's membership level: its membership points for its real
629	     * household size mapped to the numeric level. Used to establish the household's current maximum
630	     * level when capping a new owner's level.
631	     */
632	    private int membershipLevelForOwner(Owner owner) {
633	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
634	        return OwnerMapper.membershipLevelFor(points);
635	    }
