679	    /**
680	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
681	     * forward, just like a weekend, until it reaches a non-holiday business day.
682	     */
683	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
684	        LocalDate.of(2026, 1, 1),
685	        LocalDate.of(2026, 1, 26),
686	        LocalDate.of(2026, 4, 25),
687	        LocalDate.of(2026, 12, 25),
688	        LocalDate.of(2026, 12, 28));
689	
690	    /**
691	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
692	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
693	     * the effective registration date (whether supplied in the request or defaulted to the server date)
694	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
695	     * from the registration date uses the adjusted date.
696	     *
697	     * @param date the effective registration date (supplied or defaulted), never {@code null}
698	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
699	     */
700	    private static LocalDate toBusinessDay(LocalDate date) {
701	        LocalDate adjusted = date;
702	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
703	            adjusted = adjusted.plusDays(1);
704	        }
705	        return adjusted;
706	    }
