708	    /** Whether {@code date} falls on a Saturday or Sunday. */
709	    private static boolean isWeekend(LocalDate date) {
710	        DayOfWeek day = date.getDayOfWeek();
711	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
712	    }
