714	    /** Matches a well-formed postcode: exactly four decimal digits. */
715	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
716	
717	    /**
718	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
719	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
720	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
721	     * present here and accepts any well-formed postcode.
722	     */
723	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
724	        "NSW", new int[] {2000, 2099},
725	        "VIC", new int[] {3000, 3099},
726	        "QLD", new int[] {4000, 4099});
727	
728	    /**
729	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
730	     * optional, so the request contract stays backward-compatible). When present it must be exactly
731	     * four digits and, for a city whose region is known, fall within that region's inclusive range
732	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
733	     * postcode. A malformed or out-of-range value is rejected with a 400.
734	     *
735	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
736	     * @param city the owner's city, used to look up the region whose range constrains the postcode
737	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
738	     */
739	    private void validatePostcode(String postcode, String city) {
740	        if (postcode == null) {
741	            return;
742	        }
743	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
744	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
745	        }
746	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
747	        int[] range = REGION_POSTCODES.get(region);
748	        if (range == null) {
749	            return;
750	        }
751	        int value = Integer.parseInt(postcode);
752	        if (value < range[0] || value > range[1]) {
753	            throw new InvalidFieldValueException("postcode",
754	                "Postcode must be valid for the city's region " + region);
755	        }
756	    }
