758	    /**
759	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
760	     * date defaults to the server date). When present it must not be later than the current server
761	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
762	     *
763	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
764	     * @throws InvalidFieldValueException if the supplied date is later than the server date
765	     */
766	    private void validateRegistrationDate(LocalDate registrationDate) {
767	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
768	            throw new InvalidFieldValueException("registrationDate",
769	                "Registration date must not be later than the current date");
770	        }
771	    }
