801	    /**
802	     * Computes the owner's {@code riskFlag}: {@code true} when any of three conditions hold, otherwise
803	     * {@code false}. The owner is risky when it is a possible (soft) duplicate, when its email domain
804	     * is disposable-adjacent (see {@link #isDisposableAdjacentEmail(String)}), or when its city is over
805	     * its soft capacity (see {@link #isCityOverSoftCapacity(String)}). Any one condition is sufficient.
806	     *
807	     * @param owner the owner whose risk flag is computed
808	     * @return {@code true} when the owner is a possible duplicate, has a disposable-adjacent email
809	     *         domain, or lives in a city over its soft capacity; otherwise {@code false}
810	     */
811	    private boolean computeRiskFlag(Owner owner) {
812	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
813	            || isDisposableAdjacentEmail(owner.getEmail())
814	            || isCityOverSoftCapacity(owner.getCity());
