817	    /**
818	     * Returns whether {@code email}'s domain is disposable-adjacent: its domain equals one of the known
819	     * disposable-mailbox domains ({@link #DISPOSABLE_EMAIL_DOMAINS}) or is a subdomain of one (ends with
820	     * a dot followed by that domain, e.g. {@code inbox.mailinator.com}). Exact-domain matches are
821	     * rejected outright when an owner is created, so in practice this catches the subdomains that slip
822	     * past the create-time blocklist. The comparison is case-insensitive and returns {@code false} for a
823	     * {@code null}, blank, or malformed (no {@code '@'}) address.
824	     *
825	     * @param email the owner's stored email, or {@code null} when absent
826	     * @return {@code true} when the email's domain is on or under a known disposable domain
827	     */
828	    private static boolean isDisposableAdjacentEmail(String email) {
829	        if (email == null || email.isBlank()) {
830	            return false;
831	        }
832	        int at = email.lastIndexOf('@');
833	        if (at < 0 || at == email.length() - 1) {
834	            return false;
835	        }
836	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
837	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
838	            if (domain.equals(disposable) || domain.endsWith("." + disposable)) {
839	                return true;
840	            }
841	        }
842	        return false;
843	    }
