881	        String identityKey = ownerMapper.toIdentityKey(owner);
882	        boolean taken = this.clinicService.findAllOwners().stream()
883	            .filter(existing -> !isDeleted(existing))
884	            .map(ownerMapper::toIdentityKey)
885	            .anyMatch(identityKey::equals);
886	        if (taken) {
887	            throw new DuplicateIdentityException(identityKey);
