900	    /**
901	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate identity
902	     * check has passed, so the owner is known not to be a rejected duplicate. When an existing owner
903	     * has the same {@code soundex(lastName)} and the same {@code postcode} as this owner but a
904	     * <em>different</em> {@code identityKey}, the owner is a possible duplicate: {@code possibleDuplicate}
905	     * is set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
906	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
907	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
908	     * duplicate. An owner with no {@code postcode} never matches, since the soft match is keyed on it.
909	     *
910	     * @param owner the incoming owner, with its telephone, email and postcode populated
911	     * @param sharesHousehold whether the request opted in as a declared household member
912	     */
913	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
914	        owner.setPossibleDuplicate(false);
915	        owner.setPossibleDuplicateOf(null);
916	        if (sharesHousehold) {
917	            return;
918	        }
919	        String postcode = owner.getPostcode();
920	        if (postcode == null || postcode.isBlank()) {
921	            return;
922	        }
923	        String soundex = OwnerIdentity.soundex(owner.getLastName());
924	        String identityKey = ownerMapper.toIdentityKey(owner);
925	        this.clinicService.findAllOwners().stream()
926	            .filter(existing -> !isDeleted(existing))
927	            .filter(existing -> postcode.equals(existing.getPostcode()))
928	            .filter(existing -> soundex.equals(OwnerIdentity.soundex(existing.getLastName())))
929	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
930	            .min(java.util.Comparator.comparing(Owner::getId))
931	            .ifPresent(match -> {
932	                owner.setPossibleDuplicate(true);
933	                owner.setPossibleDuplicateOf(match.getId());
934	            });
935	    }
