937	    /**
938	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
939	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
940	     * comparisons are case-insensitive.
941	     */
942	    private static String normalizeForHousehold(String value) {
943	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
944	    }
