946	    /**
947	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
948	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
949	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
950	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
951	     * value normalizes to the empty string, so the required-field check rejects an address that is
952	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
953	     *
954	     * @param address the raw address value from the request (may be {@code null})
955	     * @return the normalized address, or the empty string when blank after normalization
956	     */
957	    private static String normalizeAddress(String address) {
958	        if (address == null) {
959	            return "";
960	        }
961	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
962	        if (collapsed.isEmpty()) {
963	            return "";
964	        }
965	        String[] tokens = collapsed.split(" ");
966	        StringBuilder sb = new StringBuilder();
967	        for (String token : tokens) {
968	            String expanded = switch (token) {
969	                case "ST" -> "STREET";
970	                case "RD" -> "ROAD";
971	                case "AVE" -> "AVENUE";
972	                default -> token;
973	            };
974	            if (sb.length() > 0) {
975	                sb.append(' ');
976	            }
977	            sb.append(expanded);
978	        }
