package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.Named;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.time.LocalDate;
import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
    @Mapping(target = "salutation", source = "owner", qualifiedByName = "toSalutation")
    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "toTelephoneDisplay")
    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
    @Mapping(target = "fiscalYear", source = "owner", qualifiedByName = "toFiscalYear")
    @Mapping(target = "membershipPoints", source = "owner", qualifiedByName = "toMembershipPoints")
    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "toMembershipLevel")
    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
    @Mapping(target = "timezone", source = "owner", qualifiedByName = "toTimezone")
    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "toContactPreference")
    @Mapping(target = "identity", source = "owner", qualifiedByName = "toIdentity")
    @Mapping(target = "apiVersion", source = "owner", qualifiedByName = "toApiVersion")
    @Mapping(target = "ageBand", source = "owner", qualifiedByName = "toAgeBand")
    @Mapping(target = "ownerSegment", source = "owner", qualifiedByName = "toOwnerSegment")
    @Mapping(target = "selfLink", source = "owner", qualifiedByName = "toSelfLink")
    OwnerDto toOwnerDto(Owner owner);

    /** The fixed version-2 tag mixed into every derived owner identifier so no version-1 value recurs. */
    String VERSION_TAG = "V2";

    /** The owner-identity API version reported at the top level of the owner response. */
    Integer API_VERSION = 2;

    /**
     * Groups the owner's version-2 identifiers — the {@code memberId} and {@code householdId} carried on
     * the owner and the derived {@code identityKey} — under the response's nested {@code identity}
     * object. Returns {@code null} when the owner is {@code null}.
     */
    @Named("toIdentity")
    default OwnerIdentityDto toIdentity(Owner owner) {
        if (owner == null) {
            return null;
        }
        OwnerIdentityDto identity = new OwnerIdentityDto();
        identity.setMemberId(owner.getMemberId());
        identity.setHouseholdId(owner.getHouseholdId());
        identity.setIdentityKey(toIdentityKey(owner));
        return identity;
    }

    /**
     * Returns the owner-identity API version, the fixed {@link #API_VERSION} ({@code 2}) reported at the
     * top level of every owner response.
     */
    @Named("toApiVersion")
    default Integer toApiVersion(Owner owner) {
        return owner == null ? null : API_VERSION;
    }

    /**
     * Derives the owner's {@code selfLink}: its canonical relative URL, {@code '/api/owners/'}
     * followed by the owner's id. Returns {@code null} when the owner has no id yet.
     */
    @Named("toSelfLink")
    default String toSelfLink(Owner owner) {
        if (owner == null || owner.getId() == null) {
            return null;
        }
        return "/api/owners/" + owner.getId();
    }

    /**
     * Derives the owner's {@code ageBand} from its {@code birthDate}, computed against the
     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18 on the registration date,
     * {@code 'ADULT'} from 18 up to and including 64, and {@code 'SENIOR'} at 65 or over. Returns
     * {@code null} when either the birth date or the registration date is absent.
     */
    @Named("toAgeBand")
    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
        if (age < 18) {
            return OwnerDto.AgeBandEnum.MINOR;
        }
        if (age < 65) {
            return OwnerDto.AgeBandEnum.ADULT;
        }
        return OwnerDto.AgeBandEnum.SENIOR;
    }

    /**
     * Derives the owner's version-2 duplicate-detection {@code identityKey}: the single key that
     * consolidates the former separate telephone, email and household checks. It is the lower-case,
     * 64-character SHA-256 hex digest of
     * {@code VERSION_TAG + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the
     * fixed {@link #VERSION_TAG} is mixed in so no version-1 identity key is reproduced, {@code
     * lowerEmail} is the email trimmed and lower-cased (or the empty string when absent) and {@code
     * soundex(lastName)} is the American Soundex code of the owner's last name. Because the telephone is
     * part of the key, two owners with the same last name (same soundex) and postcode but different
     * telephones have different identity keys; only an exact full-key match is a duplicate.
     */
    @Named("toIdentityKey")
    default String toIdentityKey(Owner owner) {
        if (owner == null) {
            return null;
        }
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
        String soundex = OwnerIdentity.soundex(owner.getLastName());
        return OwnerIdentity.sha256Hex(VERSION_TAG + telephone + "|" + email + "|" + soundex);
    }

    /**
     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}: one of
     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's {@code membershipLevel}
     * is {@code 3} or more, otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's
     * locality is a known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise
     * {@code 'REGIONAL'}.
     */
    @Named("toOwnerSegment")
    default OwnerDto.OwnerSegmentEnum toOwnerSegment(Owner owner) {
        if (owner == null) {
            return null;
        }
        Integer membershipLevel = toMembershipLevel(owner);
        boolean premium = membershipLevel != null && membershipLevel >= 3;
        boolean metro = REGION_TIMEZONE.containsKey(toLocality(owner));
        if (premium) {
            return metro ? OwnerDto.OwnerSegmentEnum.PREMIUM_METRO : OwnerDto.OwnerSegmentEnum.PREMIUM_REGIONAL;
        }
        return metro ? OwnerDto.OwnerSegmentEnum.STANDARD_METRO : OwnerDto.OwnerSegmentEnum.STANDARD_REGIONAL;
    }

    /**
     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
     * email, otherwise {@code 'PHONE'}.
     */
    @Named("toContactPreference")
    default String toContactPreference(Owner owner) {
        if (owner == null) {
            return null;
        }
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        return hasEmail ? "EMAIL" : "PHONE";
    }

    /**
     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
     */
    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /**
     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name
     * ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}).
     */
    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
        "NSW", "Australia/Sydney",
        "VIC", "Australia/Melbourne",
        "QLD", "Australia/Brisbane");

    /**
     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
     * owner's locality from its postcode in preference to its city.
     */
    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /**
     * Derives the owner's canonical region, the {@code REGION} component of its {@code memberId}.
     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
     * the same region for known cities but disambiguates cities that share a name.
     */
    default String toRegion(Owner owner) {
        if (owner == null) {
            return null;
        }
        String regionByPostcode = regionForPostcode(owner.getPostcode());
        if (regionByPostcode != null) {
            return regionByPostcode;
        }
        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
    }

    /**
     * Derives the owner's locality as the {@code REGION} component of its {@code memberId} (the prefix
     * before the fixed {@code <FY><HASH8><CHK>} tail). The locality therefore shares the member id's
     * identity rather than being computed independently. When the member id is absent the region is
     * derived directly from the owner's postcode and city via {@link #toRegion(Owner)}.
     */
    @Named("toLocality")
    default String toLocality(Owner owner) {
        if (owner == null) {
            return null;
        }
        String region = regionFromMemberId(owner.getMemberId());
        if (region != null) {
            return region;
        }
        return toRegion(owner);
    }

    /** The fixed-width tail of a memberId's {@code <REGION><FY><HASH8><CHK>} core: FY (2) + HASH8 (8) + CHK (1). */
    int MEMBER_ID_TAIL_LENGTH = 11;

    /**
     * Returns the {@code <REGION><FY><HASH8><CHK>} core of a {@code memberId}, stripping any
     * collision-dedup suffix ({@code '-<n>'}). Returns {@code null} when {@code memberId} is
     * {@code null}.
     */
    private static String memberIdCore(String memberId) {
        if (memberId == null) {
            return null;
        }
        int dash = memberId.indexOf('-');
        return dash >= 0 ? memberId.substring(0, dash) : memberId;
    }

    /**
     * Extracts the {@code REGION} component (the prefix before the fixed {@code <FY><HASH8><CHK>}
     * tail) from a {@code memberId}, or {@code null} when the id is absent or too short to carry one.
     */
    private static String regionFromMemberId(String memberId) {
        String core = memberIdCore(memberId);
        if (core == null || core.length() <= MEMBER_ID_TAIL_LENGTH) {
            return null;
        }
        return core.substring(0, core.length() - MEMBER_ID_TAIL_LENGTH);
    }

    /**
     * Extracts the 2-digit {@code FY} component of a {@code memberId} (the two characters immediately
     * following its {@code REGION} prefix), or {@code null} when the id is absent or too short.
     */
    private static String fiscalYearFromMemberId(String memberId) {
        String core = memberIdCore(memberId);
        if (core == null || core.length() <= MEMBER_ID_TAIL_LENGTH) {
            return null;
        }
        int fyStart = core.length() - MEMBER_ID_TAIL_LENGTH;
        return core.substring(fyStart, fyStart + 2);
    }

    /**
     * Derives the owner's {@code timezone} as the IANA timezone name mapped from its locality/region
     * via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Returns {@code null} when the
     * owner's region is not one of the tabled regions.
     */
    @Named("toTimezone")
    default String toTimezone(Owner owner) {
        if (owner == null) {
            return null;
        }
        return REGION_TIMEZONE.get(toLocality(owner));
    }

    /**
     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
     * {@code null} when the postcode is absent, malformed, or in no known range.
     */
    private static String regionForPostcode(String postcode) {
        if (postcode == null || !postcode.matches("\\d{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
     */
    @Named("toDisplayName")
    default String toDisplayName(Owner owner) {
        if (owner == null) {
            return null;
        }
        return owner.getLastName() + ", " + owner.getFirstName();
    }

    /**
     * Composes the owner's {@code salutation}: the owner's {@code title} and {@code lastName} joined
     * by a single space when a title is present, or just the {@code lastName} when no title is
     * supplied (absent or blank).
     */
